import sys, json
try:
    data = json.loads(sys.stdin.read())
except ValueError:
    raise SystemExit(1)
if not isinstance(data, dict):
    raise SystemExit(1)
import asyncio
if not isinstance(data.get("scores"),list) or any(type(value) is not int for value in data["scores"]):
    raise SystemExit(1)
async def summarize(values):
    unique = set(values)
    await asyncio.sleep(0)
    return {"count":len(unique),"passed":sum(value >= 60 for value in unique),"total":sum(unique)}
print(json.dumps(asyncio.run(summarize(data["scores"])),sort_keys=True))
